using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Linq;
using System.Text;

public static class Dataframe {
    public record Row(int number, Dictionary<string, string> values) {
        public double Numeric(string name) {
            string value = values[name];
            return value == null ? double.NaN : double.Parse(value);
        }
    }
    public sealed class Frame {
        public List<string> columns;
        public List<Row> rows = new();
    }
    public sealed class Settings {
        public Dictionary<string, string[]> values = new();
        public double Number(string key) {
            return double.Parse(values[key][0]);
        }
        public int Integer(string key) {
            return int.Parse(values[key][0]);
        }
        public int Width() {
            return int.Parse(values["PLOT"][0]);
        }
        public int Height() {
            return int.Parse(values["PLOT"][1]);
        }
        public double Limit() {
            return double.Parse(values["PLOT"][2]);
        }
    }
    public record Data(Frame frame, Frame predictions, HashSet<string> categorical, List<string> models,
                       Settings settings) {
    }
    public static List<string> Lines(string name) {
        return File.ReadAllLines(Path.Combine("input", name), Encoding.ASCII).ToList();
    }
    public static Frame ReadFrame(string name) {
        List<string> lines = Lines(name);
        Frame f = new Frame();
        f.columns = new(lines[0].Split(',').ToList());
        for (int i = 1; i < lines.Count; i++) {
            string[] words = lines[i].Split(',');
            Dictionary<string, string> values = new();
            for (int j = 0; j < words.Length; j++)
                values[f.columns[j]] = words[j].Equals("NA") ? null : words[j];
            f.rows.Add(new Row(i, values));
        }
        return f;
    }
    public static Data Read() {
        Frame frame = ReadFrame("data.csv");
        HashSet<string> categorical = new();
        foreach (string column in frame.columns)
            foreach (Row row in frame.rows) {
                string value = row.values[column];
                if (value != null && value[0] >= 'A' && value[0] <= 'Z')
                    categorical.Add(column);
            }
        Settings s = new Settings();
        foreach (string line in Lines("params.txt")) {
            string[] words = line.Split(' ');
            s.values[words[0]] = words[1..words.Length];
        }
        return new Data(frame, ReadFrame("predict.csv"), categorical, Lines("model.txt"), s);
    }
}

using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Linq;
using System.Text;

public static class Diagnostics {
    public sealed class Result {
        public double[] standardized, studentized, cooks, dffits;
        public string[] flags;
        public double[][] dfbetas;
        public double dw, bp, bpP, jb, jbP, skewness, kurtosis;
        public int bpDegrees;
    }
    public static Result Compute(double[][] x, double[] y, double[] w, QrSolver.Fit fit, double sigma,
                                 int degrees, Dataframe.Settings settings) {
        int n = y.Length, r = fit.rank;
        Result result = new Result();
        result.standardized = new double[n];
        result.studentized = new double[n];
        result.cooks = new double[n];
        result.dffits = new double[n];
        result.flags = new string[n];
        result.dfbetas = Enumerable.Range(0, n)
                             .Select(
                                 _ => new double[r])
                             .ToArray();
        for (int i = 0; i < n; i++) {
            double h = fit.leverage[i], z = fit.epsilon[i] / (sigma * Math.Sqrt(1 - h));
            result.standardized[i] = z;
            result.studentized[i] = z * Math.Sqrt((degrees - 1) / (degrees - z * z));
            result.cooks[i] = z * z * h / (r * (1 - h));
            result.dffits[i] = result.studentized[i] * Math.Sqrt(h / (1 - h));
            string flags = "";
            if (h > settings.Number("LEVERAGE") * r / n)
                flags += "H";
            if (Math.Abs(result.studentized[i]) > settings.Number("STUDENTIZED"))
                flags += "O";
            if (result.cooks[i] > settings.Number("COOK") / n)
                flags += "C";
            if (Math.Abs(result.dffits[i]) > settings.Number("DFFITS") * Math.Sqrt((double)r / n))
                flags += "F";
            result.flags[i] = flags.Length == 0 ? "-" : flags;
            double deleted = sigma * Math.Sqrt((degrees - z * z) / (degrees - 1));
            for (int k = 0; k < r; k++)
                result.dfbetas[i][k] =
                    fit.g[i][k] * fit.epsilon[i] / (1 - h) / (deleted * Math.Sqrt(fit.variance[k]));
        }
        double dw = 0;
        for (int i = 1; i < n; i++) {
            double difference = fit.epsilon[i] - fit.epsilon[i - 1];
            dw += difference * difference;
        }
        result.dw = dw / fit.rss;
        double[][] accepted = Enumerable.Range(0, n)
                                  .Select(
                                      _ => new double[r])
                                  .ToArray();
        double[] squares = new double[n], ones = new double[n];
        double sum = 0;
        for (int i = 0; i < n; i++) {
            for (int k = 0; k < r; k++)
                accepted[i][k] = x[i][fit.accepted[k]];
            squares[i] = fit.epsilon[i] * fit.epsilon[i];
            sum += squares[i];
            ones[i] = 1;
        }
        QrSolver.Fit auxiliary = QrSolver.Solve(accepted, squares, ones, settings.Number("RANK_TOL"));
        double mean = sum / n, total = 0;
        foreach (double value in squares)
            total += (value - mean) * (value - mean);
        result.bp = n * (1 - auxiliary.rss / total);
        result.bpDegrees = auxiliary.rank - 1;
        result.bpP = Inference.Pchi(result.bp, result.bpDegrees);
        sum = 0;
        foreach (double value in fit.epsilon)
            sum += value;
        mean = sum / n;
        double m2 = 0, m3 = 0, m4 = 0;
        foreach (double value in fit.epsilon) {
            double delta = value - mean;
            m2 += delta * delta;
            m3 += delta * delta * delta;
            m4 += delta * delta * delta * delta;
        }
        m2 /= n;
        m3 /= n;
        m4 /= n;
        result.skewness = m3 / (m2 * Math.Sqrt(m2));
        result.kurtosis = m4 / (m2 * m2);
        result.jb =
            n / 6.0 * (result.skewness * result.skewness + (result.kurtosis - 3) * (result.kurtosis - 3) / 4);
        result.jbP = Inference.Pchi(result.jb, 2);
        return result;
    }
}

using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Linq;
using System.Text;

public static class Formula {
    public record Factor(string name, string column, int power, bool categorical) {
    }
    public static Factor ParseFactor(string name) {
        if (name.StartsWith("C("))
            return new Factor(name, name.Substring(2, name.Length - 1 - (2)), 1, true);
        if (name.StartsWith("I(")) {
            int caret = name.IndexOf('^');
            return new Factor(name, name.Substring(2, caret - (2)),
                              int.Parse(name.Substring(caret + 1, caret + 2 - (caret + 1))), false);
        }
        return new Factor(name, name, 1, false);
    }
    public sealed class Term {
        public string name;
        public List<Factor> factors;
        public HashSet<string> names = new();
        public Term(List<string> words) {
            factors = new();
            foreach (string word in words) {
                factors.Add(ParseFactor(word));
                names.Add(word);
            }
            name = string.Join(":", words);
        }
    }
    public static bool Contained(Term a, Term b) {
        return a.names.Count < b.names.Count && b.names.IsSupersetOf(a.names);
    }
    public sealed class Model {
        public string response, weight, original;
        public List<Term> terms = new();
        public HashSet<string> variables = new();
        public HashSet<string> factorColumns = new();
    }
    public static void Add(Model model, List<string> factors) {
        Term term = new Term(factors);
        foreach (Term old in model.terms)
            if (old.names.SetEquals(term.names))
                return;
        model.terms.Add(term);
    }
    public static Model Parse(string line) {
        Model model = new Model();
        int weighted = line.IndexOf(" weights=");
        model.original = weighted < 0 ? line : line.Substring(0, weighted - (0));
        model.weight = weighted < 0 ? null : line.Substring(weighted + 9);
        int split = model.original.IndexOf(" ~ ");
        model.response = model.original.Substring(0, split - (0));
        foreach (string expression in model.original.Substring(split + 3).Split(" + ",
                                                                                StringSplitOptions.None)) {
            if (!expression.Contains("*"))
                Add(model, expression.Split(':').ToList());
            else {
                List<string> factors = expression.Split('*').ToList();
                for (int size = 1; size <= factors.Count; size++)
                    for (int mask = 1; mask < (1 << factors.Count); mask++)
                        if (System.Numerics.BitOperations.PopCount((uint)mask) == size) {
                            List<string> selected = new();
                            for (int i = 0; i < factors.Count; i++)
                                if ((mask & (1 << i)) != 0)
                                    selected.Add(factors[i]);
                            Add(model, selected);
                        }
            }
        }
        foreach (Term term in model.terms)
            foreach (Factor factor in term.factors)
                model.factorColumns.Add(factor.column);
        model.variables.UnionWith(model.factorColumns);
        model.variables.Add(model.response);
        if (model.weight != null)
            model.variables.Add(model.weight);
        return model;
    }
    public record Component(Factor factor, string name, string level) {
        public double Value(Dataframe.Row row) {
            if (factor.categorical)
                return row.values[factor.column].Equals(level) ? 1 : 0;
            double v = row.Numeric(factor.column);
            return factor.power == 1 ? v : factor.power == 2 ? v * v : v * v * v;
        }
    }
    public sealed class Column {
        public string name;
        public int term;
        public List<Component> components;
        public Column(string name, int term, List<Component> components) {
            this.name = name;
            this.term = term;
            this.components = components;
        }
        public double Value(Dataframe.Row row) {
            double product = 1;
            foreach (Component component in components)
                product *= component.Value(row);
            return product;
        }
    }
    public sealed class Design {
        public Model model;
        public List<Dataframe.Row> rows = new();
        public Dictionary<string, List<string>> levels = new();
        public List<Column> columns = new();
        public double[] y, w;
        public Design(Model model, Dataframe.Frame frame) {
            this.model = model;
            foreach (Dataframe.Row row in frame.rows) {
                bool valid = true;
                foreach (string column in model.variables)
                    if (row.values[column] == null)
                        valid = false;
                if (valid)
                    rows.Add(row);
            }
            foreach (Term term in model.terms)
                foreach (Factor factor in term.factors)
                    if (factor.categorical && !levels.ContainsKey(factor.column)) {
                        SortedSet<string> values = new(StringComparer.Ordinal);
                        foreach (Dataframe.Row row in rows)
                            values.Add(row.values[factor.column]);
                        levels[factor.column] = new(values);
                    }
            columns.Add(new Column("(Intercept)", -1, new()));
            for (int t = 0; t < model.terms.Count; t++) {
                Term term = model.terms[t];
                List<List<Component>> choices = new();
                int count = 1;
                foreach (Factor factor in term.factors) {
                    List<Component> components = new();
                    if (factor.categorical) {
                        List<string> values = levels[factor.column];
                        for (int i = 1; i < values.Count; i++)
                            components.Add(new Component(factor, factor.name + values[i], values[i]));
                    } else
                        components.Add(new Component(factor, factor.name, null));
                    choices.Add(components);
                    count *= components.Count;
                }
                for (int ordinal = 0; ordinal < count; ordinal++) {
                    int rest = ordinal;
                    List<Component> components = new();
                    List<string> names = new();
                    foreach (List<Component> list in choices) {
                        Component component = list[rest % list.Count];
                        rest /= list.Count;
                        components.Add(component);
                        names.Add(component.name);
                    }
                    columns.Add(new Column(string.Join(":", names), t, components));
                }
            }
            y = new double[rows.Count];
            w = new double[rows.Count];
            for (int i = 0; i < rows.Count; i++) {
                y[i] = rows[i].Numeric(model.response);
                w[i] = model.weight == null ? 1 : rows[i].Numeric(model.weight);
            }
        }
        public int[] Indices(int mask) {
            List<int> result = new();
            for (int j = 0; j < columns.Count; j++)
                if (columns[j].term < 0 || (mask & (1 << columns[j].term)) != 0)
                    result.Add(j);
            int[] indices = new int[result.Count];
            for (int i = 0; i < indices.Length; i++)
                indices[i] = result[i];
            return indices;
        }
        public double[][] Matrix(int[] indices) {
            double[][] result = Enumerable.Range(0, rows.Count)
                                    .Select(
                                        _ => new double[indices.Length])
                                    .ToArray();
            for (int i = 0; i < rows.Count; i++)
                for (int j = 0; j < indices.Length; j++)
                    result[i][j] = columns[indices[j]].Value(rows[i]);
            return result;
        }
        public bool Predictable(Dataframe.Row row) {
            foreach (string name in model.factorColumns) {
                string value = row.values[name];
                if (value == null || (levels.ContainsKey(name) && !levels[name].Contains(value)))
                    return false;
            }
            return true;
        }
        public double[] Vector(Dataframe.Row row) {
            double[] result = new double[columns.Count];
            for (int j = 0; j < result.Length; j++)
                result[j] = columns[j].Value(row);
            return result;
        }
    }
    public static string Display(Model model, int mask) {
        List<string> terms = new();
        for (int t = 0; t < model.terms.Count; t++)
            if ((mask & (1 << t)) != 0)
                terms.Add(model.terms[t].name);
        return model.response + " ~ " + (terms.Count == 0 ? "1" : string.Join(" + ", terms));
    }
    public static bool Removable(Model model, int mask, int term) {
        if ((mask & (1 << term)) == 0)
            return false;
        for (int t = 0; t < model.terms.Count; t++)
            if ((mask & (1 << t)) != 0 && Contained(model.terms[term], model.terms[t]))
                return false;
        return true;
    }
    public static bool Hierarchical(Model model, int mask) {
        for (int t = 0; t < model.terms.Count; t++)
            if ((mask & (1 << t)) != 0)
                for (int a = 0; a < model.terms.Count; a++)
                    if (Contained(model.terms[a], model.terms[t]) && (mask & (1 << a)) == 0)
                        return false;
        return true;
    }
}

using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Linq;
using System.Text;

public static class Inference {
    public static string Repeat(this string s, int count) => string.Concat(Enumerable.Repeat(s, count));
    public static double LogGamma(double x) {
        double[] c = { 76.18009172947146,  -86.50532032941677,   24.01409824083091,
                       -1.231739572450155, 0.001208650973866179, -0.000005395239384953 };
        double t = x + 5.5, total = t - (x + 0.5) * Math.Log(t), sum = 1.000000000190015;
        for (int j = 1; j <= c.Length; j++)
            sum += c[j - 1] / (x + j);
        return -total + Math.Log(2.5066282746310005 * sum / x);
    }
    public static double Small(double value) {
        return Math.Abs(value) < 1e-300 ? 1e-300 : value;
    }
    public static double BetaFraction(double a, double b, double x) {
        double c = 1, d = 1 / Small(1 - (a + b) * x / (a + 1)), h = d;
        for (int m = 1; m <= 1000; m++) {
            double q = m * (b - m) * x / ((a - 1 + 2 * m) * (a + 2 * m));
            d = 1 / Small(1 + q * d);
            c = Small(1 + q / c);
            h *= d * c;
            q = -(a + m) * (a + b + m) * x / ((a + 2 * m) * (a + 1 + 2 * m));
            d = 1 / Small(1 + q * d);
            c = Small(1 + q / c);
            double delta = d * c;
            h *= delta;
            if (Math.Abs(delta - 1) < 1e-15)
                break;
        }
        return h;
    }
    public static double Beta(double x, double a, double b) {
        if (x <= 0)
            return 0;
        if (x >= 1)
            return 1;
        double front =
            Math.Exp(LogGamma(a + b) - LogGamma(a) - LogGamma(b) + a * Math.Log(x) + b * Math.Log(1 - x));
        return x < (a + 1) / (a + b + 2) ? front * BetaFraction(a, b, x) / a
                                         : 1 - front * BetaFraction(b, a, 1 - x) / b;
    }
    public static double GammaQ(double a, double x) {
        if (x == 0)
            return 1;
        double front = Math.Exp(-x + a * Math.Log(x) - LogGamma(a));
        if (x < a + 1) {
            double t = 1 / a, sum = t, e = a;
            for (int i = 0; i < 1000; i++) {
                e += 1;
                t *= x / e;
                sum += t;
                if (Math.Abs(t) < Math.Abs(sum) * 1e-15)
                    break;
            }
            return 1 - sum * front;
        }
        double b = x + 1 - a, c = 1 / 1e-300, d = 1 / b, h = d;
        for (int i = 1; i <= 1000; i++) {
            double q = -i * (i - a);
            b += 2;
            d = 1 / Small(q * d + b);
            c = Small(b + q / c);
            double delta = d * c;
            h *= delta;
            if (Math.Abs(delta - 1) < 1e-15)
                break;
        }
        return front * h;
    }
    public static double Pt(double t, int degrees) {
        return Beta((double)degrees / (degrees + t * t), degrees / 2.0, 0.5);
    }
    public static double Pf(double f, int a, int b) {
        return Beta((double)b / (b + a * f), b / 2.0, a / 2.0);
    }
    public static double Pchi(double value, int degrees) {
        return GammaQ(degrees / 2.0, value / 2);
    }
    public static double Quantile(double confidence, int degrees) {
        double lo = 0, hi = 1000;
        for (int i = 0; i < 100; i++) {
            double mid = (lo + hi) / 2;
            if (Pt(mid, degrees) > 1 - confidence)
                lo = mid;
            else
                hi = mid;
        }
        return (lo + hi) / 2;
    }
    public static string Mark(double p) {
        return p < 0.001 ? "***" : p < 0.01 ? "**" : p < 0.05 ? "*" : p < 0.1 ? "." : "";
    }
    public static string Real(double value) {
        if (double.IsNaN(value))
            return "NA";
        string text = value.ToString("F4", CultureInfo.InvariantCulture);
        return text.Equals("-0.0000") ? "0.0000" : text;
    }
    public static string Pvalue(double value) {
        return double.IsNaN(value) ? "NA" : value < 0.0001 ? "<0.0001" : Real(value);
    }
}

using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Linq;
using System.Text;

public static class Program {
    public static Dataframe.Data data;
    public static Dataframe.Settings settings;
    public static List<Analysis> analyses = new();
    public static string Real(double value) {
        return Inference.Real(value);
    }
    public static string Pvalue(double value) {
        return Inference.Pvalue(value);
    }
    public static string Integer(int value) {
        return Convert.ToString(value);
    }
    public static void Write(string name, List<string> lines) {
        File.WriteAllText(Path.Combine("output", name), string.Join("\n", lines) + "\n", Encoding.ASCII);
    }
    public record TableRow(List<string> fields, string mark) {
    }
    public static TableRow Plain(params string[] fields) {
        return new TableRow(fields.ToList(), "");
    }
    public static TableRow Marked(string mark, params string[] fields) {
        return new TableRow(fields.ToList(), mark);
    }
    public static List<string> Table(List<string> header, List<TableRow> rows) {
        int[] widths = new int[header.Count];
        List<TableRow> all = new();
        all.Add(new TableRow(header, ""));
        all.AddRange(rows);
        foreach (TableRow row in all)
            for (int c = 0; c < row.fields.Count; c++)
                widths[c] = Math.Max(widths[c], row.fields[c].Length);
        List<string> output = new();
        foreach (TableRow row in all) {
            string line = "";
            for (int c = 0; c < row.fields.Count; c++) {
                string field = row.fields[c], padding = " ".Repeat(widths[c] - field.Length);
                line += c == 0 ? field + padding : "  " + padding + field;
            }
            if (row.mark.Length != 0)
                line += " " + row.mark;
            output.Add(line.TrimEnd());
        }
        return output;
    }
    public sealed class Stats {
        public int n, rank, degrees;
        public double sigma, sumWeights, total, r2, adjusted, f, fp, likelihood, aic, bic, press, predicted;
        public Stats(QrSolver.Fit fit, double[] y, double[] w) {
            n = y.Length;
            rank = fit.rank;
            degrees = n - rank;
            sigma = Math.Sqrt(fit.rss / degrees);
            double weighted = 0, logWeights = 0;
            for (int i = 0; i < n; i++) {
                sumWeights += w[i];
                weighted += w[i] * y[i];
                logWeights += Math.Log(w[i]);
            }
            double mean = weighted / sumWeights;
            for (int i = 0; i < n; i++)
                total += w[i] * (y[i] - mean) * (y[i] - mean);
            r2 = 1 - fit.rss / total;
            adjusted = 1 - (1 - r2) * (n - 1) / degrees;
            f = rank > 1 ? ((total - fit.rss) / (rank - 1)) / (fit.rss / degrees) : double.NaN;
            fp = rank > 1 ? Inference.Pf(f, rank - 1, degrees) : double.NaN;
            likelihood = 0.5 * (logWeights -
                                n * (Math.Log(2 * 3.141592653589793) + 1 - Math.Log(n) + Math.Log(fit.rss)));
            aic = -2 * likelihood + 2 * (rank + 1);
            bic = -2 * likelihood + Math.Log(n) * (rank + 1);
            for (int i = 0; i < n; i++) {
                double v = fit.epsilon[i] / (1 - fit.leverage[i]);
                press += v * v;
            }
            predicted = 1 - press / total;
        }
    }
    public sealed class Subfit {
        public int mask;
        public int[] indices;
        public double[][] x;
        public QrSolver.Fit fit;
        public Stats stats;
        public Subfit(Formula.Design design, int mask) {
            this.mask = mask;
            indices = design.Indices(mask);
            x = design.Matrix(indices);
            fit = QrSolver.Solve(x, design.y, design.w, settings.Number("RANK_TOL"));
            stats = new Stats(fit, design.y, design.w);
        }
    }
    public sealed class Analysis {
        public Formula.Design design;
        public Dictionary<int, Subfit> cache = new();
        public int mask;
        public Subfit full;
        public Diagnostics.Result diagnostics;
        public int[] acceptedIndex;
        public double critical;
        public int predicted, errors, covered;
        public double squaredError;
        public Analysis(Formula.Model model) {
            design = new Formula.Design(model, data.frame);
            mask = (1 << model.terms.Count) - 1;
            full = Fitted(mask);
            diagnostics = Diagnostics.Compute(full.x, design.y, design.w, full.fit, full.stats.sigma,
                                              full.stats.degrees, settings);
            critical = Inference.Quantile(settings.Number("CONFIDENCE"), full.stats.degrees);
            acceptedIndex = new int[design.columns.Count];
            Array.Fill(acceptedIndex, -1);
            for (int k = 0; k < full.fit.rank; k++)
                acceptedIndex[full.fit.accepted[k]] = k;
        }
        public Subfit Fitted(int selected) {
            if (!cache.ContainsKey(selected))
                cache[selected] = new Subfit(design, selected);
            return cache[selected];
        }
    }
    public record Drop(int term, int degrees, double ss, double rss, double f, double p) {
    }
    public static List<Drop> Drops(Analysis a, int mask) {
        Subfit current = a.Fitted(mask);
        List<Drop> result = new();
        for (int t = 0; t < a.design.model.terms.Count; t++)
            if (Formula.Removable(a.design.model, mask, t)) {
                Subfit removed = a.Fitted(mask & ~(1 << t));
                int degrees = current.fit.rank - removed.fit.rank;
                double ss = removed.fit.rss - current.fit.rss,
                       f = degrees > 0 ? (ss / degrees) / (current.fit.rss / current.stats.degrees)
                                       : double.NaN;
                result.Add(
                    new Drop(t, degrees, ss, removed.fit.rss, f,
                             degrees > 0 ? Inference.Pf(f, degrees, current.stats.degrees) : double.NaN));
            }
        return result;
    }
    public static double Quantile(double[] sorted, double probability) {
        double position = (sorted.Length - 1) * probability;
        int index = (int)Math.Floor(position);
        return index == sorted.Length - 1
                   ? sorted[index]
                   : sorted[index] + (position - index) * (sorted[index + 1] - sorted[index]);
    }
    public static List<string> DataSummary() {
        Dataframe.Frame frame = data.frame;
        int n = frame.rows.Count;
        List<string> output =
            new(["Data: " + n + " rows, " + frame.columns.Count + " columns", "", "Numeric columns:"]);
        List<string> numeric = new();
        List<TableRow> rows = new();
        foreach (string column in frame.columns)
            if (!data.categorical.Contains(column)) {
                numeric.Add(column);
                List<double> values = new();
                double sum = 0;
                foreach (Dataframe.Row row in frame.rows)
                    if (row.values[column] != null) {
                        double value = row.Numeric(column);
                        values.Add(value);
                        sum += value;
                    }
                double mean = sum / values.Count, variance = 0, min = values[0], max = min;
                foreach (double value in values) {
                    variance += (value - mean) * (value - mean);
                    min = Math.Min(min, value);
                    max = Math.Max(max, value);
                }
                rows.Add(Plain(column, Integer(values.Count), Integer(n - values.Count), Real(mean),
                               Real(Math.Sqrt(variance / (values.Count - 1))), Real(min), Real(max)));
            }
        output.AddRange(Table(["column", "n", "missing", "Mean", "SD", "Min", "Max"], rows));
        output.Add("");
        output.Add("Categorical columns:");
        foreach (string column in frame.columns)
            if (data.categorical.Contains(column)) {
                SortedDictionary<string, int> counts = new(StringComparer.Ordinal);
                int count = 0;
                foreach (Dataframe.Row row in frame.rows) {
                    string value = row.values[column];
                    if (value != null) {
                        count++;
                        counts[value] = counts.GetValueOrDefault(value, 0) + 1;
                    }
                }
                List<string> labels = new();
                foreach (string label in counts.Keys)
                    labels.Add(label + " " + counts[label]);
                output.Add(column + ": " + count + " values, " + (n - count) + " missing, " + counts.Count +
                           " levels: " + string.Join(", ", labels));
            }
        output.Add("");
        output.Add("Correlations (pairwise complete observations):");
        rows = new();
        foreach (string left in numeric) {
            List<string> fields = new();
            fields.Add(left);
            foreach (string right in numeric) {
                double sx = 0, sy = 0;
                int count = 0;
                foreach (Dataframe.Row row in frame.rows)
                    if (row.values[left] != null && row.values[right] != null) {
                        count++;
                        sx += row.Numeric(left);
                        sy += row.Numeric(right);
                    }
                double mx = sx / count, my = sy / count, xx = 0, yy = 0, xy = 0;
                foreach (Dataframe.Row row in frame.rows)
                    if (row.values[left] != null && row.values[right] != null) {
                        double x = row.Numeric(left) - mx, y = row.Numeric(right) - my;
                        xx += x * x;
                        yy += y * y;
                        xy += x * y;
                    }
                fields.Add(Real(xy / Math.Sqrt(xx * yy)));
            }
            rows.Add(new TableRow(fields, ""));
        }
        List<string> header = new();
        header.Add("column");
        header.AddRange(numeric);
        output.AddRange(Table(header, rows));
        output.Add("");
        return output;
    }
    public static List<string> ModelSummary(Analysis a, int number) {
        Formula.Design d = a.design;
        QrSolver.Fit fit = a.full.fit;
        Stats s = a.full.stats;
        Diagnostics.Result diag = a.diagnostics;
        List<string> terms = new(), aliases = new();
        foreach (Formula.Term term in d.model.terms)
            terms.Add(term.name);
        for (int j = 0; j < d.columns.Count; j++)
            if (a.acceptedIndex[j] < 0)
                aliases.Add(d.columns[j].name);
        List<string> output = new([
            "Model " + number + ": " + d.model.original, "Terms: " + string.Join(", ", terms),
            "Weights: " + (d.model.weight == null ? "none" : d.model.weight),
            "Observations: " + s.n + " used, " + (data.frame.rows.Count - s.n) + " dropped",
            "Columns: " + d.columns.Count + ", rank " + fit.rank +
                ", aliased: " + (aliases.Count == 0 ? "none" : string.Join(", ", aliases)),
            ""
        ]);
        double[] sorted = fit.epsilon.ToArray();
        Array.Sort(sorted);
        output.Add("Residuals: Min " + Real(sorted[0]) + ", 1Q " + Real(Quantile(sorted, 0.25)) +
                   ", Median " + Real(Quantile(sorted, 0.5)) + ", 3Q " + Real(Quantile(sorted, 0.75)) +
                   ", Max " + Real(sorted[sorted.Length - 1]));
        output.Add("");
        output.Add("Coefficients:");
        List<TableRow> rows = new();
        for (int j = 0; j < d.columns.Count; j++) {
            string name = d.columns[j].name;
            int k = a.acceptedIndex[j];
            if (k < 0)
                rows.Add(Plain(name, "NA", "NA", "NA", "NA"));
            else {
                double se = s.sigma * Math.Sqrt(fit.variance[k]), t = fit.beta[j] / se,
                       p = Inference.Pt(t, s.degrees);
                rows.Add(Marked(Inference.Mark(p), name, Real(fit.beta[j]), Real(se), Real(t), Pvalue(p)));
            }
        }
        output.AddRange(Table(["term", "Estimate", "Std. Error", "t value", "Pr(>|t|)"], rows));
        output.Add("---");
        output.Add("Signif. codes: 0 '***' 0.001 '**' 0.01 '*' 0.05 '.' 0.1 ' ' 1");
        output.Add("");
        output.Add("Residual standard error: " + Real(s.sigma) + " on " + s.degrees + " degrees of freedom");
        output.Add("Multiple R-squared: " + Real(s.r2) + ", Adjusted R-squared: " + Real(s.adjusted));
        output.Add("F-statistic: " + Real(s.f) + " on " + (s.rank - 1) + " and " + s.degrees +
                   " DF, p-value: " + Pvalue(s.fp));
        output.Add("Log-likelihood: " + Real(s.likelihood) + ", AIC: " + Real(s.aic) +
                   ", BIC: " + Real(s.bic));
        output.Add("PRESS: " + Real(s.press) + ", Predicted R-squared: " + Real(s.predicted));
        output.Add("");
        output.Add("Confidence intervals (level " + Real(settings.Number("CONFIDENCE")) + ", t " +
                   Real(a.critical) + "):");
        rows = new();
        for (int j = 0; j < d.columns.Count; j++) {
            int k = a.acceptedIndex[j];
            double half = k < 0 ? double.NaN : a.critical * (s.sigma * Math.Sqrt(fit.variance[k]));
            rows.Add(Plain(d.columns[j].name, Real(fit.beta[j] - half), Real(fit.beta[j] + half)));
        }
        output.AddRange(Table(["term", "Lower", "Upper"], rows));
        output.Add("");
        output.Add("Robust standard errors (HC3):");
        rows = new();
        for (int j = 0; j < d.columns.Count; j++) {
            string name = d.columns[j].name;
            int k = a.acceptedIndex[j];
            if (k < 0)
                rows.Add(Plain(name, "NA", "NA", "NA"));
            else {
                double variance = 0;
                for (int i = 0; i < s.n; i++) {
                    double omega =
                        fit.epsilon[i] * fit.epsilon[i] / ((1 - fit.leverage[i]) * (1 - fit.leverage[i]));
                    variance += omega * fit.g[i][k] * fit.g[i][k];
                }
                double se = Math.Sqrt(variance), t = fit.beta[j] / se, p = Inference.Pt(t, s.degrees);
                rows.Add(Marked(Inference.Mark(p), name, Real(se), Real(t), Pvalue(p)));
            }
        }
        output.AddRange(Table(["term", "Std. Error", "t value", "Pr(>|t|)"], rows));
        output.Add("");
        output.Add("Analysis of variance (sequential):");
        rows = new();
        for (int t = 0; t < d.model.terms.Count; t++) {
            int degrees = 0;
            double ss = 0;
            for (int k = 0; k < fit.rank; k++)
                if (d.columns[fit.accepted[k]].term == t) {
                    degrees++;
                    ss += fit.effects[k] * fit.effects[k];
                }
            if (degrees > 0) {
                double ms = ss / degrees, f = ms / (fit.rss / s.degrees),
                       p = Inference.Pf(f, degrees, s.degrees);
                rows.Add(Marked(Inference.Mark(p), d.model.terms[t].name, Integer(degrees), Real(ss),
                                Real(ms), Real(f), Pvalue(p)));
            }
        }
        rows.Add(Plain("Residuals", Integer(s.degrees), Real(fit.rss), Real(fit.rss / s.degrees)));
        output.AddRange(Table(["term", "Df", "Sum Sq", "Mean Sq", "F value", "Pr(>F)"], rows));
        output.Add("");
        output.Add("Marginal F tests (drop one term):");
        rows = new();
        foreach (Drop drop in Drops(a, a.mask))
            rows.Add(Marked(Inference.Mark(drop.p), d.model.terms[drop.term].name, Integer(drop.degrees),
                            Real(drop.ss), Real(drop.rss), Real(drop.f), Pvalue(drop.p)));
        output.AddRange(Table(["term", "Df", "Sum Sq", "RSS", "F value", "Pr(>F)"], rows));
        output.Add("");
        output.Add("Variance inflation factors:");
        rows = new();
        for (int k = 1; k < fit.rank; k++) {
            double[][] x = Enumerable.Range(0, s.n)
                               .Select(
                                   _ => new double[fit.rank - 1])
                               .ToArray();
            double[] y = new double[s.n];
            double sum = 0;
            for (int i = 0; i < s.n; i++) {
                int next = 0;
                for (int m = 0; m < fit.rank; m++)
                    if (m != k)
                        x[i][next++] = a.full.x[i][fit.accepted[m]];
                y[i] = a.full.x[i][fit.accepted[k]];
                sum += d.w[i] * y[i];
            }
            QrSolver.Fit aux = QrSolver.Solve(x, y, d.w, settings.Number("RANK_TOL"));
            double mean = sum / s.sumWeights, total = 0;
            for (int i = 0; i < s.n; i++)
                total += d.w[i] * (y[i] - mean) * (y[i] - mean);
            double r2 = 1 - aux.rss / total, vif = 1 / (1 - r2);
            rows.Add(Marked(vif > settings.Number("VIF") ? "high" : "", d.columns[fit.accepted[k]].name,
                            Real(vif)));
        }
        output.AddRange(Table(["column", "VIF"], rows));
        output.Add("");
        output.Add("Diagnostics:");
        double dwLimit = settings.Number("DURBIN_WATSON");
        output.Add("Durbin-Watson: " + Real(diag.dw) + " (" +
                   (diag.dw < dwLimit       ? "positive autocorrelation"
                    : diag.dw > 4 - dwLimit ? "negative autocorrelation"
                                            : "no autocorrelation") +
                   ")");
        output.Add("Breusch-Pagan: " + Real(diag.bp) + " on " + diag.bpDegrees +
                   " DF, p-value: " + Pvalue(diag.bpP) + " (" +
                   (diag.bpP < settings.Number("BREUSCH_PAGAN") ? "heteroscedastic" : "homoscedastic") + ")");
        output.Add("Jarque-Bera: " + Real(diag.jb) + " on 2 DF, p-value: " + Pvalue(diag.jbP) +
                   ", skewness " + Real(diag.skewness) + ", kurtosis " + Real(diag.kurtosis) + " (" +
                   (diag.jbP < settings.Number("NORMALITY") ? "non-normal" : "normal") + ")");
        double[][] resetX = Enumerable.Range(0, s.n)
                                .Select(
                                    _ => new double[fit.rank + 2])
                                .ToArray();
        for (int i = 0; i < s.n; i++) {
            for (int k = 0; k < fit.rank; k++)
                resetX[i][k] = a.full.x[i][fit.accepted[k]];
            resetX[i][fit.rank] = fit.fitted[i] * fit.fitted[i];
            resetX[i][fit.rank + 1] = fit.fitted[i] * fit.fitted[i] * fit.fitted[i];
        }
        QrSolver.Fit reset = QrSolver.Solve(resetX, d.y, d.w, settings.Number("RANK_TOL"));
        int q = reset.rank - fit.rank, resetDf = s.n - reset.rank;
        double resetF = ((fit.rss - reset.rss) / q) / (reset.rss / resetDf);
        output.Add("RESET (powers 2 and 3): F " + Real(resetF) + " on " + q + " and " + resetDf +
                   " DF, p-value: " + Pvalue(Inference.Pf(resetF, q, resetDf)));
        int outlier = 0;
        for (int i = 1; i < s.n; i++)
            if (Math.Abs(diag.studentized[i]) > Math.Abs(diag.studentized[outlier]))
                outlier = i;
        double pu = Inference.Pt(diag.studentized[outlier], s.degrees - 1);
        output.Add("Outlier test: row " + d.rows[outlier].number + ", studentized " +
                   Real(diag.studentized[outlier]) + ", unadjusted p-value: " + Pvalue(pu) +
                   ", Bonferroni p-value: " + Pvalue(Math.Min(1, s.n * pu)));
        int[] flags = new int[5];
        foreach (string flag in diag.flags) {
            if (flag.Contains("H"))
                flags[0]++;
            if (flag.Contains("O"))
                flags[1]++;
            if (flag.Contains("C"))
                flags[2]++;
            if (flag.Contains("F"))
                flags[3]++;
            if (!flag.Equals("-"))
                flags[4]++;
        }
        output.Add("Flagged rows: leverage " + flags[0] + ", outlier " + flags[1] + ", cooks " + flags[2] +
                   ", dffits " + flags[3] + ", any " + flags[4]);
        output.Add("Largest Cook's distances:");
        List<int> order = new();
        for (int i = 0; i < s.n; i++)
            order.Add(i);
        order.Sort((i, j) => {
            int comparison = diag.cooks[j].CompareTo(diag.cooks[i]);
            return comparison != 0 ? comparison : i.CompareTo(j);
        });
        for (int position = 0; position < Math.Min(3, s.n); position++) {
            int i = order[position];
            output.Add("row " + d.rows[i].number + ": cooks_d " + Real(diag.cooks[i]) + ", leverage " +
                       Real(fit.leverage[i]) + ", studentized " + Real(diag.studentized[i]) + ", flags " +
                       diag.flags[i]);
        }
        output.Add("Largest absolute DFBETAS:");
        rows = new();
        for (int k = 0; k < fit.rank; k++) {
            int best = 0;
            for (int i = 1; i < s.n; i++)
                if (Math.Abs(diag.dfbetas[i][k]) > Math.Abs(diag.dfbetas[best][k]))
                    best = i;
            rows.Add(Plain(d.columns[fit.accepted[k]].name, Integer(d.rows[best].number),
                           Real(diag.dfbetas[best][k])));
        }
        output.AddRange(Table(["column", "row", "DFBETAS"], rows));
        return output;
    }
    public static void Predictions() {
        List<string> output =
            new(["model,row,fit,se_fit,conf_lower,conf_upper,pred_lower,pred_upper,actual,error,covered"]);
        for (int model = 0; model < analyses.Count; model++) {
            Analysis a = analyses[model];
            QrSolver.Fit fit = a.full.fit;
            double sigma = a.full.stats.sigma;
            foreach (Dataframe.Row row in data.predictions.rows) {
                string prefix = (model + 1) + "," + row.number + ",";
                if (!a.design.Predictable(row)) {
                    output.Add(prefix + "NA,NA,NA,NA,NA,NA,NA,NA,NA");
                    continue;
                }
                a.predicted++;
                double[] x = a.design.Vector(row);
                double f = 0, variance = 0;
                for (int k = 0; k < fit.rank; k++) {
                    f += x[fit.accepted[k]] * fit.beta[fit.accepted[k]];
                    double u = 0;
                    for (int m = 0; m < fit.rank; m++)
                        u += x[fit.accepted[m]] * fit.inverse[m][k];
                    variance += u * u;
                }
                double se = sigma * Math.Sqrt(variance), ci = a.critical * se,
                       pi = a.critical * Math.Sqrt(sigma * sigma + se * se);
                string actual = "NA,NA,NA";
                if (row.values.GetValueOrDefault(a.design.model.response) != null) {
                    a.errors++;
                    double y = row.Numeric(a.design.model.response), error = y - f;
                    a.squaredError += error * error;
                    bool covered = f - pi <= y && y <= f + pi;
                    if (covered)
                        a.covered++;
                    actual = Real(y) + "," + Real(error) + "," + (covered ? "yes" : "no");
                }
                output.Add(prefix + Real(f) + "," + Real(se) + "," + Real(f - ci) + "," + Real(f + ci) + "," +
                           Real(f - pi) + "," + Real(f + pi) + "," + actual);
            }
        }
        Write("predictions.csv", output);
    }
